"use client"

import * as React from "react"
import { useAppliedFilter, useFilterActions } from "@querycn/filter-react"
import { ListFilterIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/registry/radix/ui/badge"
import { Button } from "@/registry/radix/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/registry/radix/ui/popover"
import {
  FilterBuilderPanel,
  type FilterBuilderPanelProps,
} from "@/registry/radix/filter/filter-builder-panel"

export interface FilterBuilderProps extends Omit<
  FilterBuilderPanelProps,
  "onApply" | "className"
> {
  className?: string
  /** Classes for the popover around the panel. */
  contentClassName?: string
}

/** A button showing how many filters apply; it opens the panel. Closing without Apply drops the edits. */
export function FilterBuilder({
  className,
  contentClassName,
  ...panelProps
}: FilterBuilderProps) {
  const { activeCount, messages } = useAppliedFilter()
  const { addRule, discard } = useFilterActions()
  const [open, setOpen] = React.useState(false)
  const handleOpenChange = (next: boolean) => {
    setOpen(next)
    if (!next) discard()
    // Starts an empty filter with a rule to fill in.
    else if (activeCount === 0) addRule()
  }

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm" className={className}>
          <ListFilterIcon />
          {messages.actions.open}
          {activeCount > 0 && (
            <>
              <Badge variant="secondary" aria-hidden>
                {activeCount}
              </Badge>
              <span className="sr-only">
                {messages.counts.activeFilters(activeCount)}
              </span>
            </>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className={cn("w-auto max-w-[calc(100vw-2rem)] p-3", contentClassName)}
      >
        <FilterBuilderPanel {...panelProps} onApply={() => setOpen(false)} />
      </PopoverContent>
    </Popover>
  )
}

"use client"

import * as React from "react"
import { useFilter } from "@querycn/filter-react"
import { PlusIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import { FilterJoinSelect } from "@/registry/radix/filter/filter-join-select"
import {
  FilterRuleRow,
  type FilterRuleRowProps,
} from "@/registry/radix/filter/filter-rule-row"

function lostFocus() {
  const active = document.activeElement
  return (
    !active ||
    active === document.body ||
    !active.isConnected ||
    (active as HTMLButtonElement).disabled === true
  )
}

export interface FilterBuilderPanelProps {
  valueInput?: FilterRuleRowProps["valueInput"]
  /** Offers AND/OR on the second rule. Defaults to `true`; otherwise rules keep the current join. */
  allowJoinToggle?: boolean
  /** Runs after Apply, e.g. to close a popover. */
  onApply?: () => void
  className?: string
}

/** The draft rules with Add, Clear all and Apply. Enter in a text field applies. */
export function FilterBuilderPanel({
  valueInput,
  allowJoinToggle = true,
  onApply,
  className,
}: FilterBuilderPanelProps) {
  const {
    state,
    isDirty,
    canAddRule,
    messages,
    addRule,
    setJoin,
    apply,
    reset,
  } = useFilter()
  const listRef = React.useRef<HTMLDivElement>(null)
  const addRef = React.useRef<HTMLButtonElement>(null)
  const added = React.useRef(false)
  const ids = state.rules.map((rule) => rule.id).join()
  const previousIds = React.useRef(ids)

  React.useEffect(() => {
    if (ids === previousIds.current) return
    previousIds.current = ids
    if (added.current) {
      added.current = false
      const rows = listRef.current?.querySelectorAll(
        "[data-slot=filter-rule-row]"
      )
      rows?.[rows.length - 1]?.querySelector("button")?.focus()
    } else if (lostFocus()) {
      // A removed row, Clear all, or Apply (rows remount under new ids) dropped it.
      addRef.current?.focus()
    }
  }, [ids])

  return (
    <form
      data-slot="filter-builder-panel"
      aria-label={messages.actions.open}
      className={cn("flex flex-col gap-3", className)}
      onSubmit={(event) => {
        event.preventDefault()
        // React events cross portals, so an enclosing form would submit too.
        event.stopPropagation()
        apply()
        onApply?.()
      }}
    >
      {state.rules.length === 0 ? (
        <p className="text-sm text-muted-foreground">{messages.empty.rules}</p>
      ) : (
        <div ref={listRef} className="flex flex-col gap-2">
          {state.rules.map((rule, index) => (
            <div key={rule.id} className="flex items-start gap-2">
              <div className="flex h-7 w-16 shrink-0 items-center text-sm text-muted-foreground">
                {index === 0 ? (
                  messages.join.where
                ) : index === 1 && allowJoinToggle ? (
                  <FilterJoinSelect
                    value={state.join}
                    onValueChange={setJoin}
                  />
                ) : (
                  messages.join[state.join]
                )}
              </div>
              <FilterRuleRow
                rule={rule}
                valueInput={valueInput}
                className="flex-1"
              />
            </div>
          ))}
        </div>
      )}
      <div className="flex items-center gap-2">
        <Button
          ref={addRef}
          type="button"
          variant="ghost"
          size="sm"
          disabled={!canAddRule}
          onClick={() => {
            added.current = true
            addRule()
          }}
        >
          <PlusIcon />
          {messages.actions.addRule}
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="ml-auto"
          disabled={state.rules.length === 0 && !isDirty}
          onClick={reset}
        >
          {messages.actions.clearAll}
        </Button>
        <Button type="submit" size="sm" disabled={!isDirty}>
          {messages.actions.apply}
        </Button>
      </div>
    </form>
  )
}

"use client"

import type { Join } from "@querycn/filter-core"
import { useFilterActions } from "@querycn/filter-react"

import { cn } from "@/lib/utils"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/radix/ui/select"

export interface FilterJoinSelectProps {
  value: Join
  onValueChange: (join: Join) => void
  className?: string
}

export function FilterJoinSelect({
  value,
  onValueChange,
  className,
}: FilterJoinSelectProps) {
  const { messages } = useFilterActions()
  return (
    <Select
      value={value}
      onValueChange={(next) => {
        // Inside a form Radix mirrors the value into a hidden <select>, which can report "".
        if (next === "and" || next === "or") onValueChange(next)
      }}
    >
      <SelectTrigger
        size="sm"
        aria-label={messages.join.toggle}
        className={cn("w-full", className)}
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent position="popper" align="start">
        <SelectItem value="and">{messages.join.and}</SelectItem>
        <SelectItem value="or">{messages.join.or}</SelectItem>
      </SelectContent>
    </Select>
  )
}

"use client"

import type { FilterRule } from "@querycn/filter-core"
import {
  useAppliedFilter,
  useRuleWarnings,
  type RuleWarningKey,
} from "@querycn/filter-react"
import { TriangleAlertIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/registry/radix/ui/popover"

/** A warning icon that shows what may go wrong when pressed, so it works on touch too. Nothing when there are none. */
export function FilterRuleWarnings({
  warnings,
  className,
}: {
  warnings: readonly RuleWarningKey[]
  className?: string
}) {
  const { messages } = useAppliedFilter()
  if (warnings.length === 0) return null
  const texts = warnings.map((key) => messages.warnings[key])

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label={texts.join(". ")}
          className={cn(
            "text-amber-600 hover:text-amber-600 aria-expanded:text-amber-600 dark:text-amber-500 dark:hover:text-amber-500 dark:aria-expanded:text-amber-500",
            className
          )}
        >
          <TriangleAlertIcon />
        </Button>
      </PopoverTrigger>
      <PopoverContent side="top" className="w-auto max-w-xs gap-1 p-2 text-xs">
        {texts.map((text) => (
          <p key={text}>{text}</p>
        ))}
      </PopoverContent>
    </Popover>
  )
}

/** Warnings for a draft rule. It re-renders with the draft, so the memoized row around it doesn't. */
export function FilterDraftRuleWarnings({ rule }: { rule: FilterRule }) {
  return <FilterRuleWarnings warnings={useRuleWarnings(rule)} />
}

"use client"

import * as React from "react"
import {
  findField,
  type FieldDefinition,
  type FilterRule,
  type RuleIssue,
} from "@querycn/filter-core"
import { useAppliedFilter } from "@querycn/filter-react"
import { XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import { FilterRuleWarnings } from "@/registry/radix/filter/filter-rule-warnings"
import { useRuleSummary } from "@/registry/shared/filter/filter-rule-summary"

const NO_ISSUES: readonly RuleIssue[] = []

/** The applied rules as chips; each one's × removes it right away. */
export function FilterChips({ className }: { className?: string }) {
  const { state, context, messages, ruleIssues, removeRule } =
    useAppliedFilter()
  const listRef = React.useRef<HTMLDivElement>(null)
  const focusAt = React.useRef<number | null>(null)

  // The removed chip had focus; hand it to the chip that took its place.
  React.useEffect(() => {
    if (focusAt.current === null) return
    const buttons = listRef.current?.querySelectorAll<HTMLElement>(
      "[data-slot=filter-chip-remove]"
    )
    buttons?.[Math.min(focusAt.current, buttons.length - 1)]?.focus()
    focusAt.current = null
  }, [state.rules])

  if (state.rules.length === 0) return null
  return (
    <div
      ref={listRef}
      data-slot="filter-chips"
      className={cn("flex flex-wrap items-center gap-1.5", className)}
    >
      {state.rules.map((rule, index) => {
        const field = findField(context, rule.field)
        if (!field) return null
        return (
          <React.Fragment key={rule.id}>
            {index > 0 && (
              <span className="text-xs text-muted-foreground">
                {messages.join[state.join]}
              </span>
            )}
            <FilterChip
              rule={rule}
              field={field}
              issues={ruleIssues[rule.id] ?? NO_ISSUES}
              onRemove={() => {
                focusAt.current = index
                removeRule(rule.id)
              }}
            />
          </React.Fragment>
        )
      })}
    </div>
  )
}

function FilterChip({
  rule,
  field,
  issues,
  onRemove,
}: {
  rule: FilterRule
  field: FieldDefinition
  issues: readonly RuleIssue[]
  onRemove: () => void
}) {
  const { messages } = useAppliedFilter()
  const summary = useRuleSummary(rule, field)
  const text = [summary.field, summary.operator, summary.value]
    .filter(Boolean)
    .join(" ")

  return (
    <span
      data-slot="filter-chip"
      className="inline-flex h-7 max-w-full items-center gap-0.5 rounded-md border bg-muted/50 pr-0.5 pl-2 text-xs"
    >
      <span
        title={text}
        className={cn(
          "truncate",
          // The backend ignores it, so it reads as crossed out.
          issues.includes("unsupported") && "text-muted-foreground line-through"
        )}
      >
        <span className="font-medium">{summary.field}</span>{" "}
        <span className="text-muted-foreground">{summary.operator}</span>
        {summary.value !== undefined && ` ${summary.value}`}
      </span>
      <FilterRuleWarnings warnings={issues} />
      <Button
        type="button"
        variant="ghost"
        size="icon-xs"
        data-slot="filter-chip-remove"
        aria-label={`${messages.actions.removeRule}: ${text}`}
        onClick={onRemove}
      >
        <XIcon />
      </Button>
    </span>
  )
}

"use client"

import * as React from "react"
import type { SelectOption } from "@querycn/filter-core"
import { useFilterActions } from "@querycn/filter-react"
import { CheckIcon, ChevronsUpDownIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/registry/radix/ui/command"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/registry/radix/ui/popover"

export interface FilterComboboxProps {
  id?: string
  "aria-label": string
  /** Trigger content; `undefined` shows the placeholder. */
  label: React.ReactNode | undefined
  placeholder: string
  /** Already filtered for `search`. */
  options: readonly SelectOption[]
  selected: readonly string[]
  /** Picks toggle values and the list stays open. */
  multiple?: boolean
  onSelectedChange: (values: string[]) => void
  search: string
  onSearchChange: (search: string) => void
  emptyText: string
  loading?: boolean
  error?: boolean
  onRetry?: () => void
  onOpenChange?: (open: boolean) => void
  className?: string
}

/** A searchable select of one or several values; the caller does the filtering. */
export function FilterCombobox({
  id,
  "aria-label": ariaLabel,
  label,
  placeholder,
  options,
  selected,
  multiple = false,
  onSelectedChange,
  search,
  onSearchChange,
  emptyText,
  loading = false,
  error = false,
  onRetry,
  onOpenChange,
  className,
}: FilterComboboxProps) {
  const { messages } = useFilterActions()
  const [open, setOpen] = React.useState(false)
  const handleOpenChange = (next: boolean) => {
    setOpen(next)
    // Cleared on open, not close, so the list doesn't jump during the exit animation.
    if (next) onSearchChange("")
    onOpenChange?.(next)
  }

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger asChild>
        <Button
          id={id}
          variant="outline"
          size="sm"
          role="combobox"
          aria-expanded={open}
          aria-label={ariaLabel}
          className={cn("w-40 justify-between text-sm font-normal", className)}
        >
          <span
            className={cn(
              "truncate",
              label === undefined && "text-muted-foreground"
            )}
          >
            {label ?? placeholder}
          </span>
          <ChevronsUpDownIcon className="text-muted-foreground" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-56 p-0" align="start">
        <Command shouldFilter={false}>
          <CommandInput
            placeholder={messages.placeholders.search}
            value={search}
            onValueChange={onSearchChange}
          />
          <CommandList aria-multiselectable={multiple || undefined}>
            {error ? (
              <div
                role="alert"
                className="flex flex-col items-center gap-2 py-4 text-sm text-muted-foreground"
              >
                {messages.errors.loadOptions}
                <Button variant="outline" size="xs" onClick={onRetry}>
                  {messages.actions.retry}
                </Button>
              </div>
            ) : loading ? (
              // Also shown over the previous list while the next search loads.
              <div
                role="status"
                className="py-2 text-center text-xs text-muted-foreground"
              >
                {messages.loading}
              </div>
            ) : (
              <CommandEmpty>{emptyText}</CommandEmpty>
            )}
            <CommandGroup>
              {options.map((option) => {
                const checked = selected.includes(option.value)
                return (
                  <CommandItem
                    key={option.value}
                    value={option.value}
                    // Shows the item's own check mark; several values get a checkbox instead.
                    data-checked={!multiple && checked}
                    // cmdk's aria-selected marks the highlighted item, not a picked one.
                    aria-checked={multiple ? checked : undefined}
                    onSelect={() => {
                      if (multiple) {
                        onSelectedChange(
                          checked
                            ? selected.filter((v) => v !== option.value)
                            : [...selected, option.value]
                        )
                      } else {
                        onSelectedChange([option.value])
                        handleOpenChange(false)
                      }
                    }}
                  >
                    {multiple && (
                      <span
                        aria-hidden
                        className={cn(
                          "flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-input",
                          checked &&
                            "border-primary bg-primary text-primary-foreground"
                        )}
                      >
                        {checked && <CheckIcon className="size-3" />}
                      </span>
                    )}
                    <span className="truncate">{option.label}</span>
                  </CommandItem>
                )
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

"use client"

import * as React from "react"
import { filterOptions, type FieldDefinition } from "@querycn/filter-core"
import { useFilterActions } from "@querycn/filter-react"

import { FilterCombobox } from "@/registry/radix/filter/filter-combobox"

export interface FilterFieldSelectProps {
  /** The rule's field; shown even when it isn't in `fields`. */
  field: FieldDefinition | undefined
  fields: readonly FieldDefinition[]
  onFieldChange: (name: string) => void
  className?: string
}

export function FilterFieldSelect({
  field,
  fields,
  onFieldChange,
  className,
}: FilterFieldSelectProps) {
  const { messages } = useFilterActions()
  const [search, setSearch] = React.useState("")
  const options = React.useMemo(
    () => fields.map((f) => ({ label: f.label, value: f.name })),
    [fields]
  )

  return (
    <FilterCombobox
      aria-label={messages.placeholders.field}
      label={field?.label}
      placeholder={messages.placeholders.field}
      // Matches ignoring accents, like the rest of the filter.
      options={filterOptions(options, search)}
      selected={field ? [field.name] : []}
      onSelectedChange={([name]) => {
        if (name !== undefined) onFieldChange(name)
      }}
      search={search}
      onSearchChange={setSearch}
      emptyText={messages.empty.fields}
      className={className}
    />
  )
}

"use client"

import * as React from "react"
import type { OperatorId } from "@querycn/filter-core"
import { useFilterActions, type OperatorOption } from "@querycn/filter-react"

import { cn } from "@/lib/utils"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/radix/ui/select"

export interface FilterOperatorSelectProps {
  value: OperatorId | null
  operators: readonly OperatorOption[]
  onValueChange: (operator: OperatorId) => void
  /** Id of the element to focus once an operator is picked, e.g. the value input. */
  focusAfterSelect?: string
  disabled?: boolean
  className?: string
}

export function FilterOperatorSelect({
  value,
  operators,
  onValueChange,
  focusAfterSelect,
  disabled,
  className,
}: FilterOperatorSelectProps) {
  const { messages } = useFilterActions()
  // Typeahead on the closed trigger also changes the value; only a pick from the open list moves focus.
  const open = React.useRef(false)
  const picked = React.useRef(false)

  return (
    <Select
      value={value ?? ""}
      onOpenChange={(next) => {
        open.current = next
      }}
      onValueChange={(next) => {
        // Inside a form Radix mirrors the value into a hidden <select>, which can report "".
        if (!operators.some((o) => o.id === next && o.supported)) return
        picked.current = open.current
        onValueChange(next)
      }}
      disabled={disabled || operators.length === 0}
    >
      <SelectTrigger
        size="sm"
        aria-label={messages.placeholders.operator}
        className={cn("w-44", className)}
      >
        <SelectValue placeholder={messages.placeholders.operator} />
      </SelectTrigger>
      <SelectContent
        position="popper"
        align="start"
        onCloseAutoFocus={(event) => {
          const target =
            picked.current && focusAfterSelect
              ? document.getElementById(focusAfterSelect)
              : null
          picked.current = false
          if (target) {
            event.preventDefault()
            target.focus()
          }
        }}
      >
        {operators.map((operator) => (
          <SelectItem
            key={operator.id}
            value={operator.id}
            disabled={!operator.supported}
          >
            {operator.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

"use client"

import * as React from "react"
import type {
  Arity,
  FieldDefinition,
  FilterRule,
  FilterValue,
} from "@querycn/filter-core"
import { useFilterActions, useFilterRule } from "@querycn/filter-react"
import { XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/registry/radix/ui/button"
import { FilterFieldSelect } from "@/registry/radix/filter/filter-field-select"
import { FilterOperatorSelect } from "@/registry/radix/filter/filter-operator-select"
import { FilterDraftRuleWarnings } from "@/registry/radix/filter/filter-rule-warnings"
import { FilterValueInput } from "@/registry/radix/filter/filter-value-input"

export interface FilterValueSlotProps {
  /** Put on the first focusable element; it gets focus after an operator is picked. */
  id: string
  rule: FilterRule
  field: FieldDefinition
  arity: Exclude<Arity, "none">
  setValue: (value: FilterValue) => void
}

export interface FilterRuleRowProps {
  rule: FilterRule
  /**
   * Defaults to `FilterValueInput`. A component, not a render function, so the
   * memoized row keeps its props stable.
   */
  valueInput?: React.ComponentType<FilterValueSlotProps>
  className?: string
}

export const FilterRuleRow = React.memo(function FilterRuleRow({
  rule,
  valueInput: ValueInput = FilterValueInput,
  className,
}: FilterRuleRowProps) {
  const { messages } = useFilterActions()
  const {
    field,
    fields,
    operators,
    arity,
    setField,
    setOperator,
    setValue,
    remove,
  } = useFilterRule(rule)
  const valueId = React.useId()

  return (
    <div
      data-slot="filter-rule-row"
      className={cn("flex flex-wrap items-center gap-2", className)}
    >
      <FilterFieldSelect
        field={field}
        fields={fields}
        onFieldChange={setField}
      />
      <FilterOperatorSelect
        value={rule.operator}
        operators={operators}
        onValueChange={setOperator}
        focusAfterSelect={valueId}
        disabled={!field}
      />
      {field && arity && arity !== "none" && (
        // Keyed so a new field starts with fresh input state (search, loaded options).
        <ValueInput
          key={field.name}
          id={valueId}
          rule={rule}
          field={field}
          arity={arity}
          setValue={setValue}
        />
      )}
      {/* Right-aligned so remove buttons line up across rows. */}
      <div className="ml-auto flex items-center gap-1">
        <FilterDraftRuleWarnings rule={rule} />
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={messages.actions.removeRule}
          onClick={remove}
        >
          <XIcon />
        </Button>
      </div>
    </div>
  )
})

"use client"

import type * as React from "react"
import type { FieldTypeId } from "@querycn/filter-core"

import { BooleanValueInput } from "@/registry/radix/filter/filter-boolean-value-input"
import { DateValueInput } from "@/registry/radix/filter/filter-date-value-input"
import { DateTimeValueInput } from "@/registry/radix/filter/filter-datetime-value-input"
import type { FilterValueSlotProps } from "@/registry/radix/filter/filter-rule-row"
import { SelectValueInput } from "@/registry/radix/filter/filter-select-value-input"
import { TimeValueInput } from "@/registry/radix/filter/filter-time-value-input"
import {
  NumberValueInput,
  TextValueInput,
} from "@/registry/radix/filter/filter-text-value-input"

export type FilterValueInputs = Partial<
  Record<FieldTypeId, React.ComponentType<FilterValueSlotProps>>
>

/** Value input per field type; a custom field type adds its own entry. */
export const filterValueInputs: FilterValueInputs = {
  text: TextValueInput,
  number: NumberValueInput,
  boolean: BooleanValueInput,
  select: SelectValueInput,
  multiSelect: SelectValueInput,
  date: DateValueInput,
  datetime: DateTimeValueInput,
  time: TimeValueInput,
}

export interface FilterValueInputProps extends FilterValueSlotProps {
  /** Overrides by field type, e.g. `{ ...filterValueInputs, rating: RatingInput }`. */
  inputs?: FilterValueInputs
}

/**
 * Picks the input for the rule's field type; types without one get a text
 * input, which handles single and range values only.
 */
export function FilterValueInput({
  inputs = filterValueInputs,
  ...props
}: FilterValueInputProps) {
  const { type } = props.field
  // Own keys only: a custom type id like "toString" must not hit Object.prototype.
  const Input = Object.hasOwn(inputs, type) ? inputs[type] : undefined
  return Input ? <Input {...props} /> : <TextValueInput {...props} />
}

